package com.neotvos.support;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.hardware.usb.*;import android.view.*;import android.widget.*;import android.text.InputType;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.security.*;

/** A guided phone-side TV installer. ADB authorization is always granted on the target TV. */
public final class MainActivity extends Activity{
 int BG=0xff040c1b,CARD=0xb51a3049,TEXT=0xfff4faff,MUTED=0xffb6cee2,ACCENT=0xff8feaff,RIM=0x6095cfff,FOCUS=0xe637607d;String themeName="Aurora Glass";android.graphics.Bitmap background;final ExecutorService work=Executors.newSingleThreadExecutor();final Handler ui=new Handler(Looper.getMainLooper());
 LinearLayout body;TextView status;AdbClient adb;boolean busy,closed;long generation;String target="Not connected",identity="",model="",serial="";final Set<String> homePackages=new HashSet<>(),thirdParty=new HashSet<>();final List<String> packages=new ArrayList<>();final Map<String,String> appNames=new HashMap<>();
 UsbManager usb;static final String USB_PERMISSION="com.neotvos.support.USB_PERMISSION";
 final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(!USB_PERMISSION.equals(i.getAction()))return;UsbDevice d=i.getParcelableExtra(UsbManager.EXTRA_DEVICE);if(i.getBooleanExtra(UsbManager.EXTRA_PERMISSION_GRANTED,false)&&d!=null)connectUsb(d);else message("USB permission was not granted. You can try again.");}};
 interface Job{String run()throws Exception;}
 public void onCreate(Bundle b){super.onCreate(b);loadTheme();try(java.io.InputStream in=getAssets().open("companion-lake.jpg")){background=android.graphics.BitmapFactory.decodeStream(in);}catch(Exception ignored){}getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);usb=(UsbManager)getSystemService(USB_SERVICE);IntentFilter filter=new IntentFilter(USB_PERMISSION);if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,filter);home();}
 void loadTheme(){String id=getPreferences(0).getString("theme","aurora");try(InputStream in=getAssets().open("themes/"+id+".json")){org.json.JSONObject t=new org.json.JSONObject(new String(readAll(in),"UTF-8"));ACCENT=Color.parseColor(t.getString("accent"));TEXT=Color.parseColor(t.getString("text"));MUTED=Color.parseColor(t.getString("muted"));CARD=Color.parseColor(t.getString("glass"));RIM=Color.parseColor(t.getString("rim"));FOCUS=Color.parseColor(t.getString("focus"));themeName=t.getString("name");}catch(Exception ignored){}}
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,(color&0x00ffffff)|Math.max(0x90000000,color&0xff000000)});d.setCornerRadius(dp(22));d.setStroke(dp(1),RIM);return d;}
 android.graphics.drawable.Drawable glassButton(){android.graphics.drawable.StateListDrawable states=new android.graphics.drawable.StateListDrawable();states.addState(new int[]{android.R.attr.state_focused},shape(FOCUS));states.addState(new int[]{android.R.attr.state_pressed},shape(FOCUS));states.addState(new int[]{},shape(CARD));return new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf((ACCENT&0x00ffffff)|0x44000000),states,null);}
 TextView text(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setTypeface(android.graphics.Typeface.create("sans-serif",0));v.setIncludeFontPadding(false);v.setPadding(0,dp(6),0,dp(6));return v;}
 void page(String title){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(BG);if(background!=null){ImageView image=new ImageView(this);image.setImageBitmap(background);image.setScaleType(ImageView.ScaleType.CENTER_CROP);root.addView(image,new FrameLayout.LayoutParams(-1,-1));}
  View veil=new View(this);veil.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xc6040c1b,0xe5040c1b,0xfa040c1b}));root.addView(veil,new FrameLayout.LayoutParams(-1,-1));
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(22),dp(26),dp(22),dp(32));scroll.addView(body);root.addView(scroll,new FrameLayout.LayoutParams(-1,-1));
  TextView brand=text("NEO TVos  /  COMPANION",11,ACCENT);brand.setLetterSpacing(.15f);body.addView(brand);TextView heading=text(title,27,TEXT);heading.setTypeface(android.graphics.Typeface.create("sans-serif-light",0));body.addView(heading);
  status=text(target+(model.isEmpty()?"":"\n"+model),13,MUTED);status.setPadding(dp(16),dp(13),dp(16),dp(13));status.setBackground(shape(CARD));LinearLayout.LayoutParams widget=new LinearLayout.LayoutParams(-1,-2);widget.topMargin=dp(12);widget.bottomMargin=dp(8);body.addView(status,widget);
  TextView cancel=text("Disconnect / cancel current task",12,ACCENT);cancel.setOnClickListener(v->disconnect());body.addView(cancel);setContentView(root);
 }
 void paragraph(String s){body.addView(text(s,15,MUTED));}
 void button(String label,Runnable action){TextView v=text(label,15,TEXT);v.setPadding(dp(19),dp(16),dp(19),dp(16));v.setMinHeight(dp(56));v.setGravity(Gravity.CENTER_VERTICAL);v.setBackground(glassButton());v.setFocusable(true);v.setClickable(true);v.setElevation(dp(2));v.setOnFocusChangeListener((view,focused)->view.animate().scaleX(focused?1.015f:1).scaleY(focused?1.015f:1).setDuration(160).start());v.setOnClickListener(w->{if(!busy)action.run();else Toast.makeText(this,"Please wait, or disconnect to cancel.",Toast.LENGTH_SHORT).show();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(11);body.addView(v,p);}
 void appearance(){page("Theme Studio");paragraph("The same theme palette and glass surfaces as Neo TVos. Current: "+themeName);String[] ids={"aurora","violet","midnight"},names={"Aurora Glass","Violet Dusk","Midnight Contrast"};for(int i=0;i<ids.length;i++){final String id=ids[i];button(names[i],()->{getPreferences(0).edit().putString("theme",id).apply();loadTheme();home();});}button("Back",this::home);}
 void home(){page("Set up your TV");paragraph("Connect your TV, review apps, then install Neo.");button("1  Connection guide",this::guide);button("2  Connect using Wi-Fi / Ethernet",this::networkPage);button("2  Scan USB debugging devices",this::usbPage);button("3  Read TV details",()->job("Reading TV details",()->{require();readIdentity();return identity;},this::details));button("4  Review general apps",this::loadApps);button("5  Install Neo TVos",this::confirmInstall);button("6  Set Neo as Home",this::homeOptions);button("Theme Studio / "+themeName,this::appearance);}
 void guide(){page("Connect in a few steps");paragraph("ON THE TV\n1. Open Settings → Device preferences / System → About. Select Build 7 times to enable Developer options. Menu names vary by brand.\n2. Open Developer options. Enable USB debugging. Enable Network / ADB debugging if the TV offers it.\n3. Keep the TV on. When it shows ‘Allow debugging?’, approve this phone. Only approve devices you recognize.");paragraph("WI-FI OR ETHERNET\nPut the phone and TV on the same local network. The TV may use Ethernet and the phone Wi-Fi. In TV Network settings, find its IP address. Enter that IP and the TV’s Network ADB port (often 5555). Guest Wi-Fi or router device isolation can block the connection. A cable to Ethernet alone does not enable debugging.");paragraph("USB\nThe phone must support USB host / OTG. Use a data cable and the phone’s OTG adapter. Connect to a TV/box port that supports USB device debugging, then scan and approve Android’s USB permission prompt. Many TV USB-A sockets are host-only: a USB-A-to-A cable will not make those work. Use the model’s documented debug/device port; otherwise use network ADB.");paragraph("PAIRING-CODE WIRELESS DEBUGGING\nThis version supports classic authorized Network ADB and USB. It does not implement Android 11+ pairing-code/TLS ports. If your TV only offers pairing-code debugging, pair from a computer and enable classic network ADB there, or use the supported USB path. The app can switch a working USB ADB connection to network port 5555 with your approval.");paragraph("CLEANUP & INSTALL\nRead the detected model and serial first. Review each app and confirm its removal separately. App data may be lost. Core system apps, Settings, keyboard/input services, and every detected Home app are protected. Install Neo, then select it as Home. Do not disable the original launcher.");paragraph("If a step fails, read the message before continuing. Keep the original launcher available. Turn debugging off on the TV when finished if you no longer need it.");button("Back",this::home);}
 EditText input(String hint,String value,boolean number){EditText e=new EditText(this);e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setSingleLine();e.setPadding(dp(14),dp(10),dp(14),dp(10));e.setBackground(shape(CARD));e.setHint(hint);e.setText(value);if(number)e.setInputType(InputType.TYPE_CLASS_NUMBER);body.addView(e,new LinearLayout.LayoutParams(-1,dp(56)));return e;}
 void networkPage(){page("Connect over your network");paragraph("Use the TV’s current IP and classic Network ADB port. You’ll need to approve debugging on the TV. Pairing-code ports are not supported in this build.");EditText host=input("TV IP address",getPreferences(0).getString("host",""),false),port=input("ADB port","5555",true);button("Connect to this TV",()->{String h=host.getText().toString().trim();int p;try{p=Integer.parseInt(port.getText().toString());if(p<1||p>65535||!h.matches("[A-Za-z0-9.:-]+"))throw new Exception();}catch(Exception e){message("Enter a valid TV address and port 1-65535.");return;}disconnectSilent();generation++;target=h+":"+p;job("Approve debugging on the TV if prompted",()->{adb=new AdbClient(AdbClient.tcp(h,p),AdbClient.keys(getFilesDir()));readIdentity();getPreferences(0).edit().putString("host",h).apply();return "Connected to "+model;},this::details);});button("Scan this local network for port 5555",this::scanNetwork);button("Back",this::home);}
 void scanNetwork(){String prefix="";try{for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces()))for(InetAddress a:Collections.list(n.getInetAddresses()))if(a instanceof Inet4Address&&a.isSiteLocalAddress()){String ip=a.getHostAddress();prefix=ip.substring(0,ip.lastIndexOf('.')+1);break;}}catch(Exception e){}if(prefix.isEmpty()){message("No local IPv4 network found. Enter the TV IP manually.");return;}final String subnet=prefix;confirm("Scan local devices?","Check "+subnet+"1–254 for an open port 5555. A result is only a candidate; you choose which TV to connect.",()->job("Scanning local ADB port",()->{ExecutorService pool=Executors.newFixedThreadPool(16);List<Future<String>> f=new ArrayList<>();for(int i=1;i<=254;i++){final String ip=subnet+i;f.add(pool.submit(()->{try(Socket s=new Socket()){s.connect(new InetSocketAddress(ip,5555),350);return ip;}catch(Exception e){return null;}}));}StringBuilder found=new StringBuilder();try{for(Future<String> r:f){String ip=r.get();if(ip!=null)found.append(ip).append('\n');}}finally{pool.shutdownNow();}return found.toString();},()->{}));}
 void usbPage(){page("USB debugging scan");paragraph("Connect the phone as USB host / OTG to a TV’s supported USB device/debug port. Both sides must support that connection.");int count=0;for(UsbDevice d:usb.getDeviceList().values())if(UsbWire.adbInterface(d)!=null){count++;button((d.getProductName()==null?"USB ADB device":d.getProductName())+" • "+d.getVendorId()+":"+d.getProductId(),()->{if(usb.hasPermission(d))connectUsb(d);else{Intent i=new Intent(USB_PERMISSION).setPackage(getPackageName());int flags=PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0);usb.requestPermission(d,PendingIntent.getBroadcast(this,0,i,flags));}});}if(count==0)paragraph("No USB ADB interface found. Check the data cable, OTG support, and USB debugging. A host-only TV port cannot be used this way.");button("Scan again",this::usbPage);button("Connection guide",this::guide);button("Back",this::home);}
 void connectUsb(UsbDevice d){disconnectSilent();generation++;target="USB "+d.getDeviceName();job("Approve this phone on the TV",()->{adb=new AdbClient(new UsbWire(usb,d),AdbClient.keys(getFilesDir()));readIdentity();return "USB connection authorized";},this::details);}
 void require()throws Exception{if(adb==null)throw new IOException("Connect to the TV first.");}
 String prop(String key)throws Exception{return adb.shell("getprop "+key).trim();}
 void readIdentity()throws Exception{require();String features=adb.shell("pm list features");String characteristics=prop("ro.build.characteristics");if(!features.contains("android.software.leanback")&&!features.contains("android.hardware.type.television")&&!characteristics.contains("tv")){disconnectSilent();throw new IOException("This device does not identify as Android TV / Google TV. No installation or cleanup performed.");}String sdk=prop("ro.build.version.sdk");if(!sdk.matches("[0-9]+")||Integer.parseInt(sdk)<24)throw new IOException("TV needs Android 7 / API 24 or newer for this companion's install flow.");model=prop("ro.product.brand")+" / "+prop("ro.product.manufacturer")+" "+prop("ro.product.model");serial=prop("ro.serialno");identity="Target: "+target+"\nModel: "+model+"\nSerial: "+serial+"\nAndroid: "+prop("ro.build.version.release")+" / API "+sdk+"\nFingerprint: "+prop("ro.build.fingerprint");homePackages.clear();String homes=adb.shell("cmd package query-activities --brief -a android.intent.action.MAIN -c android.intent.category.HOME");for(String l:homes.split("\\r?\\n")){String v=l.trim();if(v.matches("[A-Za-z0-9_.]+/[A-Za-z0-9_.$]+"))homePackages.add(v.split("/")[0]);}if(homePackages.isEmpty())throw new IOException("Could not identify Home apps; mutations are blocked.");}
 void verifyTarget()throws Exception{require();if(homePackages.isEmpty())throw new IOException("Read TV details successfully before making changes.");if(!prop("ro.serialno").equals(serial))throw new IOException("TV identity changed. Reconnect and review the target.");String user=adb.shell("am get-current-user").trim();if(!user.equals("0"))throw new IOException("Switch the TV to its owner profile (user 0) first.");}
 void details(){page("Check your TV");paragraph(identity);button("Review general apps",this::loadApps);if(target.startsWith("USB"))button("Enable classic Network ADB on port 5555",()->confirm("Enable Network ADB?","The TV will accept network debugging on port 5555 until turned off. Use only a trusted local network. Find the TV IP in Network settings, then reconnect using Wi-Fi/Ethernet.",()->job("Enabling network ADB",()->{verifyTarget();String s=adb.enableTcp();disconnectSilent();return s+"\nReconnect by entering the TV IP. Turn Network debugging off after use.";},this::networkPage)));button("Back",this::home);}
 void loadApps(){job("Reading general apps and names",()->{verifyTarget();packages.clear();thirdParty.clear();appNames.clear();byte[] helper;try(InputStream in=getAssets().open("inventory.jar")){helper=readAll(in);}try{
  adb.uploadInventory(new ByteArrayInputStream(helper),helper.length);
  String output=adb.shell("CLASSPATH=/data/local/tmp/neo-support-inventory.jar app_process /system/bin com.neotvos.support.InventoryMain");String begin="NEO_INVENTORY_BEGIN\n",end="\nNEO_INVENTORY_END";output=output.replace("\r","");int start=output.indexOf(begin),finish=output.indexOf(end,start+begin.length());if(start<0||finish<0)throw new IOException("Could not read real app names from this TV. No cleanup was performed. "+output);
  org.json.JSONArray rows=new org.json.JSONArray(output.substring(start+begin.length(),finish));for(int i=0;i<rows.length();i++){org.json.JSONObject row=rows.getJSONObject(i);String pkg=row.getString("package");boolean system=row.getBoolean("system");if(row.optBoolean("launchable",false)&&CleanupPolicy.canRemove(pkg,!system,homePackages)){packages.add(pkg);appNames.put(pkg,row.getString("name"));if(!system)thirdParty.add(pkg);}}
 }finally{try{adb.shell("rm -f /data/local/tmp/neo-support-inventory.jar");}catch(Exception ignored){}}
 packages.sort((a,b)->appNames.get(a).compareToIgnoreCase(appNames.get(b)));return packages.size()+(packages.size()==1?" general app loaded.":" general apps loaded.")+" Required Android components are excluded.";},this::appsPage);}
 void appsPage(){page("General apps");paragraph("Select an app to review removal. Required Android components are excluded.");List<String> display=new ArrayList<>(packages);display.sort(java.util.Comparator.comparingInt(p->CleanupPolicy.canRemove(p,thirdParty.contains(p),homePackages)?0:1));for(String pkg:display){boolean removable=CleanupPolicy.canRemove(pkg,thirdParty.contains(pkg),homePackages);String name=appNames.getOrDefault(pkg,pkg);if(removable)button(name+"\n"+pkg,()->confirm("Remove "+name+"?","TV: "+model+" ("+target+")\nPackage: "+pkg+"\nRemove for owner profile 0. App data/accounts may be lost. Preinstalled apps may be restored from firmware; downloaded apps require reinstalling. No automatic backup is made.",()->job("Removing only "+pkg,()->{verifyTarget();if(!CleanupPolicy.canRemove(pkg,thirdParty.contains(pkg),homePackages))throw new IOException("Protected app");String result=adb.shell("pm uninstall --user 0 "+pkg);if(!result.contains("Success"))throw new IOException(result);return "Removed "+pkg+" for owner profile 0.";},()->{packages.remove(pkg);appsPage();})));}button("Back",this::home);}
 void confirmInstall(){if(adb==null){message("Connect to a TV first.");return;}confirm("Install Neo TVos?","Install the bundled Neo launcher on "+model+" ("+target+"). Existing Neo data is preserved when the signature matches. Other apps are not removed. Home selection is a separate step.",()->job("Installing Neo; keep this phone connected",()->{verifyTarget();long length;try(android.content.res.AssetFileDescriptor fd=getAssets().openFd("Neo-TVos.apk")){length=fd.getLength();}String expected;try(InputStream in=getAssets().open("Neo-TVos.sha256")){expected=new String(readAll(in),"UTF-8").trim();}MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=getAssets().open("Neo-TVos.apk")){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}StringBuilder hex=new StringBuilder();for(byte b:digest.digest())hex.append(String.format(Locale.US,"%02x",b&255));if(!hex.toString().equals(expected))throw new IOException("Bundled APK hash mismatch");try(InputStream in=getAssets().open("Neo-TVos.apk")){String result=adb.install(in,length,(sent,total)->{if(sent%262144<4096)ui.post(()->{if(status!=null)status.setText("Installing… "+sent*100/total+"%");});});if(!result.contains("Success"))throw new IOException(result);return "Neo installed successfully. Choose Set Neo as Home next.";}},this::home));}
 void homeOptions(){page("Neo Home setup");paragraph("Try the normal Home setting first. Some manufacturers keep their launcher as the system default. Home-button compatibility can route Home presses to Neo while keeping the original launcher installed.");button("Set Android default Home to Neo",this::confirmHome);button("Enable Home-button compatibility",this::confirmCompatibility);button("Undo companion-enabled Home compatibility",this::undoCompatibility);button("Back",this::home);}
 String compatKey(){return "compat-before:"+target+":"+serial;}
 void confirmCompatibility(){if(adb==null){message("Connect to the TV first.");return;}confirm("Enable Neo Home-button compatibility?","TV: "+model+" ("+target+")\nEnable Neo's accessibility service on the TV and open Neo. This routes Home presses and supports app-lock expiry by observing foreground package names. It does not read screen contents. Existing accessibility services stay enabled. The original launcher stays installed. You can undo this companion action here.",()->job("Enabling Neo Home compatibility",()->{verifyTarget();if(!adb.shell("dumpsys package com.tvos.neo").contains("NeoHomeService"))throw new IOException("Install Neo first.");String component="com.tvos.neo/com.tvos.neo.NeoHomeService";String raw=adb.shell("settings get secure enabled_accessibility_services").trim();List<String> services=new ArrayList<>();if(!raw.equals("null")&&!raw.isEmpty())for(String service:raw.split(":")){if(!service.matches("[A-Za-z0-9_.]+/[A-Za-z0-9_.$]+"))throw new IOException("Unrecognized accessibility component. Use the TV settings instead.");services.add(service);}String key=compatKey();if(!getPreferences(0).contains(key))getPreferences(0).edit().putString(key,raw).apply();if(!services.contains(component))services.add(component);String joined=String.join(":",services);adb.shell("settings put secure enabled_accessibility_services '"+joined+"'");adb.shell("settings put secure accessibility_enabled 1");if(!adb.shell("settings get secure enabled_accessibility_services").contains(component))throw new IOException("TV did not retain the accessibility setting. Enable Neo in the TV Accessibility settings.");adb.shell("am start -n com.tvos.neo/.NeoHomeActivity");return "Neo Home-button compatibility is enabled. Press Home on the TV remote to verify. The OEM launcher remains installed.";},this::homeOptions));}
 void undoCompatibility(){if(adb==null){message("Connect first.");return;}String before=getPreferences(0).getString(compatKey(),null);if(before==null){message("This phone has no saved compatibility record for this TV.");return;}confirm("Undo Neo Home-button compatibility?","Remove only Neo's accessibility component if this companion added it. Preserve other current accessibility services. If Neo was already enabled before the companion action, leave it enabled.",()->job("Restoring Home compatibility",()->{verifyTarget();String component="com.tvos.neo/com.tvos.neo.NeoHomeService";if(!before.contains(component)){String current=adb.shell("settings get secure enabled_accessibility_services").trim();List<String> keep=new ArrayList<>();if(!current.equals("null")&&!current.isEmpty())for(String service:current.split(":")){if(!service.matches("[A-Za-z0-9_.]+/[A-Za-z0-9_.$]+"))throw new IOException("Unrecognized service; restore from TV settings.");if(!service.equals(component))keep.add(service);}if(keep.isEmpty()){adb.shell("settings delete secure enabled_accessibility_services");adb.shell("settings put secure accessibility_enabled 0");}else adb.shell("settings put secure enabled_accessibility_services '"+String.join(":",keep)+"'");}getPreferences(0).edit().remove(compatKey()).apply();return "Compatibility state restored. Other accessibility services were preserved.";},this::homeOptions));}
 void confirmHome(){if(adb==null){message("Connect to a TV first.");return;}confirm("Set Neo as Home?","Set com.tvos.neo/.NeoHomeActivity as the TV's Home and open it. The original launcher stays installed. On TVs that ignore this choice, Neo offers Home-button accessibility setup; enable that on the TV yourself.",()->job("Setting Neo as Home",()->{verifyTarget();String path=adb.shell("pm path com.tvos.neo");if(!path.contains("package:"))throw new IOException("Install Neo first.");String previous=adb.shell("cmd package resolve-activity --brief -a android.intent.action.MAIN -c android.intent.category.HOME");File report=new File(getFilesDir(),"previous-home-"+System.currentTimeMillis()+".txt");try(FileOutputStream out=new FileOutputStream(report)){out.write((identity+"\nPrevious Home:\n"+previous).getBytes("UTF-8"));}String result=adb.shell("cmd package set-home-activity com.tvos.neo/.NeoHomeActivity");if(!result.toLowerCase(Locale.ROOT).contains("success"))throw new IOException("Home selection not confirmed: "+result);adb.shell("am start -n com.tvos.neo/.NeoHomeActivity");String selected=adb.shell("cmd package resolve-activity --brief -a android.intent.action.MAIN -c android.intent.category.HOME");if(!selected.contains("com.tvos.neo/"))throw new IOException("This TV keeps its OEM default launcher. Use Home setup > Enable Home-button compatibility, or select Neo in the TV default-app settings.");return "Neo is now Home. Original Home:\n"+previous;},this::home));}
 static byte[] readAll(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}
 void styleDialog(AlertDialog d){if(d.getWindow()!=null){d.getWindow().setBackgroundDrawable(shape(CARD));WindowManager.LayoutParams lp=d.getWindow().getAttributes();lp.dimAmount=.65f;d.getWindow().setAttributes(lp);}TextView message=d.findViewById(android.R.id.message);if(message!=null)message.setTextColor(TEXT);int titleId=getResources().getIdentifier("alertTitle","id","android");TextView title=d.findViewById(titleId);if(title!=null)title.setTextColor(TEXT);if(d.getButton(-1)!=null)d.getButton(-1).setTextColor(ACCENT);if(d.getButton(-2)!=null)d.getButton(-2).setTextColor(MUTED);}
 void confirm(String title,String detail,Runnable yes){AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setMessage(detail).setPositiveButton("Yes, proceed",(dialog,w)->yes.run()).setNegativeButton("Cancel",null).create();d.show();styleDialog(d);}
 void message(String s){if(!closed){AlertDialog d=new AlertDialog.Builder(this).setTitle("Neo TVos Companion").setMessage(s).setPositiveButton("OK",null).create();d.show();styleDialog(d);}}
 void job(String title,Job task,Runnable after){if(busy)return;busy=true;final long startedGeneration=generation;if(status!=null)status.setText(title);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);work.execute(()->{String result;try{result=task.run();}catch(Exception e){String error=e.getMessage()==null?e.toString():e.getMessage();boolean lost=adb!=null&&!adb.connected();ui.post(()->{if(closed||generation!=startedGeneration)return;busy=false;getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(lost){disconnectSilent();target="Connection lost";networkPage();message("Reconnect to the same TV and refresh its app list before retrying. Check whether the previous action finished. Details: "+error);}else message(error);});return;}final String text=result;ui.post(()->{if(closed||generation!=startedGeneration)return;busy=false;getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(!closed){after.run();message(text);}});});}
 void disconnectSilent(){AdbClient old=adb;adb=null;if(old!=null)old.close();model="";serial="";identity="";packages.clear();thirdParty.clear();appNames.clear();homePackages.clear();}
 void disconnect(){generation++;disconnectSilent();target="Not connected";busy=false;home();}
 @Override protected void onDestroy(){closed=true;disconnectSilent();work.shutdownNow();try{unregisterReceiver(receiver);}catch(Exception ignored){}super.onDestroy();}
 @Override public void onBackPressed(){if(busy){message("Use Disconnect now to cancel the current task.");return;}home();}
}
